TLM.f("Sancti/05-11r",{"officium":"Ss. Philippi et Jacobi Apostolorum","rule":["Gloria","Credo"],"sections":{"Introitus":[{"k":"ref","la":"Neh 9:27"},{"k":"text","la":"Clamavérunt ad te, Dómine, in témpore afflictiónis suæ, et tu de cœlo exaudísti eos, allelúja, allelúja."},{"k":"ref","la":"Ps 32:1"},{"k":"text","la":"Exsultáte, justi, in Dómino: rectos decet collaudátio."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Clamavérunt ad te, Dómine, in témpore afflictiónis suæ, et tu de cœlo exaudísti eos, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Deus, qui nos ánnua Apostolórum tuórum Philíppi et Jacóbi sollemnitáte lætíficas: præsta, quǽsumus: ut, quorum gaudémus méritis, instruámur exémplis."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 5:1-5"},{"k":"text","la":"Stabunt justi in magna constántia advérsus eos, qui se angustiavérunt et qui abstulérunt labóres eórum. Vidéntes turbabúntur timore horríbili, et mirabúntur in subitatióne insperátæ salútis, dicéntes intra se, pœniténtiam agéntes, et præ angústia spíritus geméntes: Hi sunt, quos habúimus aliquándo in derísum et in similitúdinem impropérii. Nos insensáti vitam illórum æstimabámus insániam, et finem illórum sine honóre: ecce, quómodo computáti sunt inter fílios Dei, et inter Sanctos sors illórum est."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: etenim veritátem tuam in ecclésia sanctórum. Allelúja."},{"k":"ref","la":"Ps 14:9"},{"k":"text","la":"Tanto témpore vobíscum sum, et non cognovístis me? Philíppe, qui videt me, videt et Patrem meum. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 14:1-13"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Non turbátur cor vestrum. Creditis in Deum, et in me crédite. In domo Patris mei mansiónes multæ sunt. Si quo minus, dixíssem vobis: Quia vado paráre vobis locum. Et si abíero et præparávero vobis locum: íterum vénio et accípiam vos ad meípsum, ut, ubi sum ego, et vos sitis. Et quo ego vado, scitis, et viam scitis. Dicit ei Thomas: Dómine, nescímus, quo vadis: et quómodo póssumus viam scire? Dicit ei Jesus: Ego sum via et véritas et vita; nemo venit ad Patrem nisi per me. Si cognovissétis me, et Patrem meum útique cognovissétis: et ámodo cognoscátis eum, et vidístis eum. Dicit ei Philíppus: Dómine, osténde nobis Patrem, et sufficit nobis. Dicit ei Jesus: Tanto témpore vobíscum sum, et non cognovístis me? Philíppe, qui videt me, videt et Patrem. Quómodo tu dicis: Osténde nobis Patrem? Non créditis, quia ego in Patre, et Pater in me est? Verba, quæ ego loquor vobis, a meípso non loquor. Pater autem in me manens, ipse facit ópera. Non créditis, quia ego in Patre, et Pater in me est? Alióquin propter ópera ipsa crédite. Amen, amen, dico vobis, qui credit in me, ópera, quæ ego fácio, et ipse fáciet, et majóra horum fáciet: quia ego ad Patrem vado. Et quodcúmque petiéritis Patrem in nómine meo, hoc fáciam."}],"Offertorium":[{"k":"ref","la":"Ps 88:6"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: et veritátem tuam in ecclésia sanctórum, allelúja, allelúja."}],"Secreta":[{"k":"text","la":"Múnera, Dómine, quæ pro Apostolórum tuórum Philippi et Jacóbi sollemnitáte deférimus, propítius súscipe: et mala ómnia, quæ merémur avérte."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joannes 14:9; 14:10"},{"k":"text","la":"Tanto témpore vobíscum sum, et non cognovístis me? Philíppe, qui videt me, videt et Patrem meum, allelúja: non credis, quia ego in Patre, et Pater in me est? Allelúja, allelúja."}],"Postcommunio":[{"k":"text","la":"Quǽsumus, Dómine, salutáribus repléti mystériis: ut, quorum sollémnia celebrámus, eórum oratiónibus adjuvémur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"3276b843590f880b":{"t":"Neh* 9, 27, Ps 32, 1\n(Neh* 9, 27) Zavapiše k tebi, Gospodine, u vrijeme svoje nevolje i ti si ih s nebesa uslišio, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 32, 1) Radujte se, pravednici, u Gospodinu, pravednima dolikuje pohvala!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Neh* 9, 27) Zavapiše k tebi, Gospodine, u vrijeme svoje nevolje i ti si ih s nebesa uslišio, <i>aleluja</i>, <i>aleluja</i>.\n[* Vulgata Sixto-Clementina sadrži dvije knjige o Ezri, od kojih se druga novijim izdanjima označavaju kao knjiga Nehemijina: I Esdr i II Esdr odgovaraju Ezr i Neh]","v":"i esdr vel neh → ∅; i esdr vel neh → ∅"},"355805c9859de29b":{"t":"<i>Pomolimo se</i>.\nBože, koji nas razveseljuješ godišnjom svetkovinom svojih apostola Filipa i Jakova, podaj, molimo, da nas pouči primjer onih čijim se zaslugama radujemo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"c600ca35b26cf613":{"t":"Mudr 5, 1-5\nČitanje knjige Mudrosti. Pravednici će se junački održati protiv onih koji su ih tlačili i oteli plodove njihova truda. Kad ih bezbožnici vide, smest će se od užasnog straha i čudit će se neočekivanom njihovu spasu. Mislit će u sebi očajni i jecajući od duševne boli: To su oni kojima smo se mi nekada rugali i koje smo grdili. Mi lude! Držali smo njihov život ludošću i njihov svršetak nečasnim. A evo, kako su pribrojeni djeci Božjoj i njihova je baština među svetima."},"78fc6950717cfc45":null,"958157874650a28a":{"t":"Iv 14, 1-13\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme reče Isus svojim učenicima: Neka se ne straši vaše srce. Ako vjerujete u Boga, vjerujte i u mene. U kući mojega Oca ima mnogo stanova. A bio bih vam kazao da nije tako. Idem da vam pripravim mjesto. I kad odem i pripravim mjesto, opet ću doći i uzet ću vas k sebi da budete i vi tamo gdje sam ja. A kamo ja idem, znate, i put znate. Toma mu reče: Gospodine, ne znamo kamo ideš i kako možemo znati put? Isus mu odgovori: Ja sam put, istina i život! Nitko ne dolazi k Ocu nego po meni. Kad bi vi poznali mene, poznali bi i moga Oca. I odsada ćete ga poznavati i vidjeli ste ga. Reče mu Filip: Gospodine, pokaži nam Oca i dosta nam je! Isus mu reče: Toliko sam vremena s vama, pa me niste upoznali? Filipe, koji vidi mene, vidi i Oca. Kako ti kažeš: Pokaži nam Oca? Zar ne vjerujete da sam ja u Ocu a Otac u meni? Riječi, koje vam govorim, ne govorim vam sam od sebe, nego Otac. koji je u meni, on čini djela. Zar ne vjerujete da sam ja u Ocu, a Otac u meni? Ako ne, tada vjerujte radi samih djela. Zaista, za-ista vam kažem, koji vjeruje u me, činit će i sam djela koja ja činim, a činit će još veća od ovih jer ja idem k Ocu. I štogod zamolite Oca u moje ime, to ću učiniti."},"f6559b160ccd64cf":{"t":"Ps 88, 6\nNebesa slave tvoja čudesa, Gospodine, a zbor svetih tvoju vjernost, <i>aleluja</i>, <i>aleluja</i>."},"35794f4e0ac632fb":{"t":"Primi, Gospodine, milostivo darove što ti ih prinosimo o blagdanu tvojih svetih apostola Filipa i Jakova i odvrati od nas sva zla što ih zaslužujemo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"fdbfd5e8960de5c2":{"t":"Uistinu je dostojno, i pravedno, pravo i spasonosno tebe, Gospodine, vječni Pastiru, smjerno moliti da stado svoje ne ostaviš, nego da ga po svojim blaženim apostolima neprestano štitiš i čuvaš, da njime ravnaju isti poglavari, koje si mu postavio na čelo kao pastire i namjesnike svoga djela. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"},"b6803d9269c23c13":{"t":"Iv 14, 9 et 10\nToliko sam vremena s vama, pa me ne poznate? Filipe, tko vidi mene, vidi Oca moga, <i>aleluja</i>.\nZar ne vjeruješ da sam ja u Ocu a Otac u meni, <i>aleluja</i>, <i>aleluja</i>."},"8f97cddf4173d144":{"t":"<i>Pomolimo se</i>.\nNasićeni spasonosnim tajnama, molimo, Gospodine, da nas pomažu molitve onih kojih svetkovinu slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
